import neopixel

n = 3
np = neopixel.NeoPixel(pin_RGB,n)

def bounce(cycles, delay):
    for i in range(n * cycles):
        for j in range(n):
            np[j] = (0, 0, 128)
        if (i // n) % 2 == 0:
            np[i % n] = (0, 0, 0)
        else:
            np[n - 1 - (i % n)] = (0, 0, 0)
        np.show()
        sleep(delay)

bounce(10, 200)

