import neopixel

n = 3
np = neopixel.NeoPixel(pin_RGB,n)

def fade(cycles, delay):
    for i in range(0, cycles * 256, 8):
        for j in range(n):
            if (i // 256) % 2 == 0:
                val = i & 0xff
            else:
                val = 255 - (i & 0xff)
            np[j] = (val, 0, 0)
        np.show()
        sleep(delay)

fade(10, 50)

